const $=id=>document.getElementById(id),fmt=n=>Math.round(n).toLocaleString('ru-RU'),compact=n=>n>=1e6?(n/1e6).toLocaleString('ru-RU',{maximumFractionDigits:1})+' млн':n>=10000?(n/1000).toLocaleString('ru-RU',{maximumFractionDigits:1})+' тыс.':fmt(n);
const paths={food:'M4 4v6m3-6v6m3-6v6M4 8h6v3a3 3 0 0 1-6 0M7 14v7M19 21V3c-5 3-5 9 0 10',fish:'M3 12c4-7 11-7 15 0-4 7-11 7-15 0Zm15 0 4-5v10ZM7 11h.1',stone:'m3 16 5-11 9-2 5 12-7 6-10-1Zm5-11 6 9 8 1M3 16l11-2 1 7',tools:'m5 21 14-16M5 4c4-3 10-1 15 5M13 8l5 4M3 19l3 3',shield:'m12 2 9 4v6c0 5-5 8-9 10-4-2-9-5-9-10V6Zm0 4v12M6 9h12',leaf:'M4 20c1-10 7-16 17-17 0 11-5 17-14 15M3 21 16 8',grain:'M12 22V4M12 9C7 9 5 6 5 3c5 0 7 3 7 6Zm0 6c5 0 7-3 7-6-5 0-7 3-7 6Zm0 4c-5 0-7-3-7-6 5 0 7 3 7 6Z',bell:'M5 17h14l-2-4V9a5 5 0 0 0-10 0v4Zm5 3h4M12 2v2',settings:'M4 7h16M4 17h16M8 4v6M16 14v6',calc:'M5 3h14v18H5ZM8 7h8M8 12h1m5 0h2m-8 5h1m5 0h2'};
const icon=name=>`<svg aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[name]||paths.tools}"/></svg>`;
const groupOf=id=>GROUPS.find(g=>g[0]===RESOURCE_ROWS.find(r=>r[0]===id)[2]),nameOf=id=>RESOURCE_ROWS.find(r=>r[0]===id)?.[1]||'Нет открытых блюд';
let scenario,stock,policies,selected='cooked_fish',filter='food',query='',enabled=false,preview=null,pinned=false,openGroup=null,hideTimer,toastTimer;
function initialize(){scenario=structuredClone(DEMO);stock={...INITIAL_STOCK};policies=Object.fromEntries(RESOURCE_ROWS.map(r=>[r[0],{mode:'auto',target:0,priority:r[3]==='meal'?3:2,margin:null}]));
 const initial={cooked_meat:64,cooked_fish:40,cooked_berries:32,dried_meat:16,medicine:4,animal_feed:12,arrows:60,combat_bow:2,stone_spear:4,wooden_shield:4,leather_clothing:8};for(const [id,n] of Object.entries(initial))policies[id].target=n;
 policies.berries={mode:'manual',target:40,priority:2,margin:null};policies.wood_log={mode:'manual',target:160,priority:2,margin:null};
 enabled=false;preview=null;selected='cooked_fish';filter='food';query='';$('search').value='';$('days').value=scenario.days;$('stock-days').value=scenario.stockDays;$('buffer').value=scenario.buffer;$('continuous').checked=true;
 document.querySelectorAll('[data-scenario]').forEach(el=>el.value=scenario[el.dataset.scenario]);closePopover();render();}
function notify(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500);}
function current(){return calculate(scenario,stock,policies);}
function manualCount(){return Object.values(policies).filter(p=>p.mode==='manual').length;}
function shortCount(){return RESOURCE_ROWS.filter(r=>policies[r[0]].target>(stock[r[0]]||0)).length;}
function renderHud(){
 $('resident-count').textContent=`${fmt(scenario.population)} жителей · ${scenario.hunters} охотников · ${scenario.soldiers} военных`;
 $('resource-groups').innerHTML=GROUPS.map(([id,name,gicon])=>{const rows=RESOURCE_ROWS.filter(r=>r[2]===id),sum=rows.reduce((a,r)=>a+(stock[r[0]]||0),0);return `<button class="groupchip" data-group="${id}" aria-expanded="${openGroup===id}" aria-controls="popover" title="${name}: ${fmt(sum)} единиц"><span class="groupname">${icon(gicon)}<span>${name}</span></span><span><strong>${compact(sum)}</strong><small>${rows.length} видов · склад</small></span></button>`;}).join('');
 $('bell').innerHTML=icon('bell')+`<span class="notification-count">${shortCount()?2:1}</span>`;$('settings').innerHTML=icon('settings');$('auto-icon').innerHTML=icon('calc');
 document.querySelectorAll('[data-group]').forEach(el=>{el.onpointerenter=()=>{if(!pinned)showGroup(el.dataset.group,el);clearTimeout(hideTimer);};el.onpointerleave=()=>scheduleHide();el.onfocus=()=>{if(!pinned)showGroup(el.dataset.group,el);};el.onclick=()=>{if(pinned&&openGroup===el.dataset.group){closePopover();return;}pinned=true;showGroup(el.dataset.group,el);};});
 const ready=MEALS.reduce((a,id)=>a+(stock[id]||0),0);$('food-cover').textContent=scenario.population?(ready/(scenario.population*3)).toLocaleString('ru-RU',{maximumFractionDigits:1})+' дня':'Нет жителей';
 $('short-count').textContent=shortCount()+' ресурсов';const amount=Object.values(stock).reduce((a,b)=>a+b,0);$('capacity').textContent=`${compact(amount)} / ${compact(scenario.capacity)}`;
 $('capacity').classList.toggle('deficit',amount>scenario.capacity);
 $('policy-status').textContent=enabled&&$('continuous').checked?'Автоцели обновляются':`Ручных целей: ${manualCount()} · расчёт по кнопке`;
}
function renderRows(){
 $('filters').innerHTML=[['all','Все'],...GROUPS].map(([id,name])=>`<button class="${filter===id?'active':''}" data-filter="${id}">${name}</button>`).join('');
 const rows=RESOURCE_ROWS.filter(r=>(filter==='all'||r[2]===filter)&&r[1].toLowerCase().includes(query.toLowerCase()));
 $('stock-rows').innerHTML=rows.map(r=>{const [id,name]=r,p=policies[id],short=Math.max(0,p.target-(stock[id]||0)),raw=['chain','zero'].includes(r[3]);return `<tr class="${selected===id?'selected':''}"><td><button class="resource-name" data-select="${id}">${icon(id.includes('fish')?'fish':groupOf(id)[2])}<span>${name}</span></button></td><td title="На доступных складах поселения">${fmt(stock[id]||0)}</td><td><input type="number" min="0" max="10000000" value="${p.target}" data-target="${id}" aria-label="Цель: ${name}"></td><td><button class="mode ${p.mode==='manual'?'manual':''}" data-mode="${id}" aria-label="Режим цели: ${name}">${p.mode==='manual'?'Ручная':'Авто'}</button></td><td><select data-priority="${id}" aria-label="Приоритет: ${name}">${['Пауза','Низкий','Обычный','Высокий','Срочный'].map((n,i)=>`<option value="${i}" ${p.priority===i?'selected':''}>${n}</option>`).join('')}</select></td><td><input type="number" min="0" max="200" placeholder="${raw?'0%':'Общая'}" value="${p.margin??''}" data-margin="${id}" title="Надбавка в процентах. Пусто: ${raw?'0% для сырья':'общая настройка'}" aria-label="Надбавка %: ${name}"></td><td class="${short?'':'zero'}">${short?'−'+fmt(short):'—'}</td></tr>`;}).join('')||'<tr><td colspan="7">Ничего не найдено. Попробуйте другое название.</td></tr>';
 $('row-count').textContent=`${rows.length} из ${RESOURCE_ROWS.length} ресурсов`;
}
function detailHtml(){const r=RESOURCE_ROWS.find(r=>r[0]===selected),p=policies[selected],c=current(),short=Math.max(0,p.target-(stock[selected]||0));return `<div class="detail-icon">${icon(selected.includes('fish')?'fish':groupOf(selected)[2])}</div><div class="eyebrow">${groupOf(selected)[1]}</div><h2>${r[1]}</h2><p>${r[4]}</p><div class="numbers"><div><small>План на ${scenario.days} дней</small><b>${fmt(c.month[selected])}</b></div><div><small>Дефицит склада</small><b class="${short?'deficit':''}">${fmt(short)}</b></div></div><h3>ПРАВИЛО ДЛЯ ЭТОГО РЕСУРСА</h3><p>${r[5]}</p><div class="formula">${c.why[selected]}${p.mode==='manual'?'<br><b>Сейчас ручная цель '+fmt(p.target)+'. Пересчёт её не заменит.</b>':''}</div><h3>МЕСЯЦ ≠ СКЛАД НА МЕСЯЦ</h3><p>Месяц — полный план потребления и входов. Цель на складе — ближайшие ${scenario.stockDays} дня + запас. Входы рецептов учитывают готовые вещи на складе.</p>`;}
function renderDetail(){$('detail').innerHTML=detailHtml();}
function renderMenu(){const c=current();$('month-total').textContent=fmt(c.menu.filter(Boolean).length*scenario.population*3)+' порций / месяц';
 $('menu-calendar').innerHTML=c.menu.map((id,i)=>`<button data-day="${i}" class="day ${id||'missing'}" title="День ${i+1}: ${nameOf(id)}, ${scenario.population*3} порций" aria-label="День ${i+1}: ${nameOf(id)}, изменить"><small>${i+1}</small>${icon(id==='cooked_fish'?'fish':id==='cooked_berries'?'leaf':id==='dried_meat'?'grain':'food')}<span>${id==='cooked_fish'?'Рыба':id==='cooked_meat'?'Мясо':id==='cooked_berries'?'Ягоды':id==='dried_meat'?'Вяленое':'Нет рецепта'}</span></button>`).join('');
 $('opened-recipes').innerHTML='<span>Открытые рецепты в примере:</span>'+MEALS.map(id=>`<label><input type="checkbox" data-opened="${id}" ${scenario.opened.includes(id)?'checked':''}>${nameOf(id)}</label>`).join('');
}
function renderPlan(){const c=current();$('resource-plan').innerHTML=GROUPS.map(([g,name])=>`<section class="plan-group"><h2>${name}</h2><div class="plan-cards">${RESOURCE_ROWS.filter(r=>r[2]===g).map(r=>`<article class="plan-card"><h3>${r[1]}<span>${fmt(c.month[r[0]])} / план</span></h3><small>${r[4]}</small><p>${r[5]}</p></article>`).join('')}</div></section>`).join('');}
function render(){renderHud();renderRows();renderDetail();renderMenu();renderPlan();renderPreview();}
function invalidate(){preview=null;$('preview').hidden=true;}
function applyResult(c){for(const r of RESOURCE_ROWS)if(policies[r[0]].mode==='auto')policies[r[0]].target=c.target[r[0]];}
function updateFromScenario(){invalidate();if(enabled&&$('continuous').checked){const c=current();if(!c.noRecipes){applyResult(c);notify('Автоцели обновлены. Ручные значения сохранены.');}else notify('Нет открытых блюд: автообновление приостановлено.');}render();}
function renderPreview(){const host=$('preview');host.hidden=!preview;if(!preview)return;const changes=RESOURCE_ROWS.filter(r=>policies[r[0]].mode==='auto'&&policies[r[0]].target!==preview.target[r[0]]).sort((a,b)=>policies[b[0]].priority-policies[a[0]].priority);
 const total=Object.values(preview.target).reduce((a,b)=>a+b,0),overflow=Math.max(0,total-scenario.capacity);
 host.innerHTML=`<div class="preview-head"><div><h3>Расчёт готов · ${changes.length} изменений</h3><p>${scenario.population} жителей · ${scenario.days} дней меню · склад на ${scenario.stockDays} дня · резерв ${scenario.buffer}%</p></div><span class="badge">${manualCount()} ручных целей не изменятся</span></div>${preview.noRecipes?'<p class="warning">Нет открытых рецептов готовой еды. Выберите их в данных примера; применение отключено.</p>':''}${overflow?`<p class="warning">Цели требуют ${fmt(total)} мест при вместимости ${fmt(scenario.capacity)}. Не хватает ${fmt(overflow)}. План не урезан: уменьшите горизонт склада или расширьте хранение.</p>`:''}<div class="changes">${changes.map(r=>`<div class="change"><span>${r[1]} <small>План месяца: ${fmt(preview.month[r[0]])}</small></span><span>${fmt(policies[r[0]].target)} → ${fmt(preview.target[r[0]])}</span></div>`).join('')||'<p>Цели уже соответствуют плану.</p>'}</div><div class="preview-actions"><button class="primary" id="apply" ${preview.noRecipes?'disabled':''}>Применить ${changes.length} целей</button><button id="cancel-preview">Отмена</button><small>Применение меняет цели, не создаёт ресурсы.</small></div>`;
 if(preview.constraints.length)host.querySelector('.changes').insertAdjacentHTML('beforebegin',`<p class="warning">Ручные ограничения: ${preview.constraints.map(c=>`${nameOf(c.id)} — цель ${fmt(c.manual)}, расчёту нужно ${fmt(c.needed)}`).join('; ')}. Значения сохранены: для выполнения плана нужно поднять их вручную или вернуть строки в «Авто».</p>`);
 $('apply').onclick=()=>{applyResult(preview);enabled=true;invalidate();render();notify('План применён. Ручные цели сохранены.');};$('cancel-preview').onclick=()=>{invalidate();};
}
function place(anchor){const pop=$('popover'),r=anchor.getBoundingClientRect();pop.style.left=Math.max(12,Math.min(r.left,innerWidth-pop.offsetWidth-12))+'px';pop.style.top=Math.min(r.bottom+8,Math.max(12,innerHeight-pop.offsetHeight-12))+'px';}
function showGroup(id,anchor){clearTimeout(hideTimer);openGroup=id;const group=GROUPS.find(g=>g[0]===id),rows=RESOURCE_ROWS.filter(r=>r[2]===id);$('popover').hidden=false;$('popover').innerHTML=`<div class="popover-head"><h3>${group[1]}</h3><button data-close aria-label="Закрыть плашку">×</button></div><p>Доступно на складах / цель. Полные числа — без сокращения.</p>${rows.map(r=>`<div class="popover-row"><span>${r[1]}</span><b>${fmt(stock[r[0]]||0)}</b><small>/ ${fmt(policies[r[0]].target)}</small></div>`).join('')}<button class="primary" data-jump="${id}">Управлять запасами →</button>`;place(anchor);document.querySelectorAll('[data-group]').forEach(el=>el.setAttribute('aria-expanded',el.dataset.group===id));}
function closePopover(){clearTimeout(hideTimer);$('popover').hidden=true;pinned=false;openGroup=null;$('bell').setAttribute('aria-expanded','false');document.querySelectorAll('[data-group]').forEach(el=>el.setAttribute('aria-expanded','false'));}
function scheduleHide(){if(!pinned)hideTimer=setTimeout(closePopover,230);}
function showTab(id){document.querySelectorAll('.tabpage').forEach(el=>el.hidden=el.id!==id);document.querySelectorAll('[data-tab]').forEach(el=>el.setAttribute('aria-selected',el.dataset.tab===id));closePopover();}
document.addEventListener('click',e=>{
 const button=e.target.closest('button');if(!button)return;
 if(button.dataset.tab)showTab(button.dataset.tab);
 if(button.dataset.filter){filter=button.dataset.filter;renderRows();}
 if(button.dataset.select){selected=button.dataset.select;renderRows();renderDetail();if(innerWidth<=1150){pinned=true;$('popover').hidden=false;$('popover').innerHTML='<button data-close aria-label="Закрыть">×</button>'+detailHtml();place(button);}}
 if(button.dataset.mode){const p=policies[button.dataset.mode];p.mode=p.mode==='auto'?'manual':'auto';if(p.mode==='auto')enabled=false;invalidate();render();notify(p.mode==='auto'?'Строка готова к автоматике. Рассчитайте и примените план.':'Ручная цель защищена от пересчёта.');}
 if(button.hasAttribute('data-close'))closePopover();
 if(button.dataset.jump){filter=button.dataset.jump;showTab('stocks');renderRows();$('search').scrollIntoView({behavior:'smooth',block:'center'});}
 if(button.dataset.day){const day=Number(button.dataset.day),host=$('menu-editor');host.hidden=false;host.innerHTML=`<label>День ${day+1} · ${scenario.population*3} порций <select id="day-meal">${scenario.opened.map(id=>`<option value="${id}" ${monthMenu(scenario)[day]===id?'selected':''}>${nameOf(id)}</option>`).join('')}</select></label><button id="set-day" ${scenario.opened.length?'':'disabled'}>Сохранить день</button><button id="close-day">Закрыть</button>`;$('set-day').onclick=()=>{scenario.menu[day]=$('day-meal').value;host.hidden=true;updateFromScenario();};$('close-day').onclick=()=>host.hidden=true;}
});
document.addEventListener('change',e=>{const el=e.target,id=el.dataset.target||el.dataset.priority||el.dataset.margin;
 if(id){const p=policies[id];if(el.dataset.target){p.target=Math.max(0,Math.min(1e7,Number(el.value)||0));p.mode='manual';}if(el.dataset.priority)p.priority=Number(el.value);if(el.dataset.margin){p.margin=el.value===''?null:Math.max(0,Math.min(200,Number(el.value)||0));enabled=false;}invalidate();render();}
 if(el.dataset.scenario){const key=el.dataset.scenario;scenario[key]=Math.max(0,Math.min(key==='capacity'?1e8:1e4,Number(el.value)||0));scenario.hunters=Math.min(scenario.hunters,scenario.population);scenario.soldiers=Math.min(scenario.soldiers,scenario.population-scenario.hunters);scenario.sick=Math.min(scenario.sick,scenario.population);document.querySelectorAll('[data-scenario]').forEach(x=>x.value=scenario[x.dataset.scenario]);updateFromScenario();}
 if(el.dataset.opened){scenario.opened=MEALS.filter(id=>document.querySelector(`[data-opened="${id}"]`).checked);$('menu-editor').hidden=true;updateFromScenario();}
});
$('search').oninput=e=>{query=e.target.value;renderRows();};
for(const [id,key,max] of [['days','days',31],['stock-days','stockDays',30],['buffer','buffer',200]])$(id).onchange=()=>{scenario[key]=Math.max(key==='buffer'?0:1,Math.min(max,Number($(id).value)||0));$(id).value=scenario[key];enabled=false;invalidate();renderHud();renderMenu();renderDetail();renderPlan();};
$('continuous').onchange=()=>renderHud();$('calculate').onclick=()=>{preview=current();renderPreview();$('preview').scrollIntoView({behavior:'smooth',block:'nearest'});};
$('reset').onclick=()=>{initialize();notify('Демонстрация сброшена.');};
$('large-stock').onclick=()=>{stock=Object.fromEntries(RESOURCE_ROWS.map(r=>[r[0],10000]));updateFromScenario();notify('Все 41 вида по 10 000. Группы остаются на месте.');};
$('empty-stock').onclick=()=>{stock={};updateFromScenario();};$('restore-stock').onclick=()=>{stock={...INITIAL_STOCK};updateFromScenario();};
$('settings').onclick=()=>{$('scenario').open=true;$('scenario').scrollIntoView({behavior:'smooth'});};
$('pause').onclick=()=>{const paused=$('pause').getAttribute('aria-pressed')!=='true';$('pause').setAttribute('aria-pressed',paused);$('pause').textContent=paused?'Ⅱ Пауза':'▷ Идёт время';notify('Только демонстрация управления временем.');};
document.querySelectorAll('.speed').forEach(b=>b.onclick=()=>{document.querySelectorAll('.speed').forEach(x=>x.classList.toggle('active',x===b));});
$('bell').onclick=()=>{if(openGroup==='alerts'){closePopover();return;}closePopover();pinned=true;openGroup='alerts';$('bell').setAttribute('aria-expanded','true');$('popover').hidden=false;$('popover').innerHTML=`<div class="popover-head"><h3>Снабжение</h3><button data-close aria-label="Закрыть уведомления">×</button></div><div class="popover-row"><span>Ниже цели</span><b>${shortCount()} ресурсов</b></div><p>Откройте запасы, чтобы уточнить цели. Меню и формулы доступны до применения.</p><button class="primary" data-jump="all">Посмотреть запасы →</button>`;place($('bell'));};
$('popover').onpointerenter=()=>clearTimeout(hideTimer);$('popover').onpointerleave=scheduleHide;
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closePopover();$('menu-editor').hidden=true;}if(e.key==='Tab')setTimeout(()=>{if(!$('popover').contains(document.activeElement)&&!document.activeElement?.matches('[data-group]')&&!pinned)closePopover();},0);});
document.addEventListener('pointerdown',e=>{if(!$('popover').hidden&&!e.target.closest('#popover,[data-group],#bell'))closePopover();});
window.addEventListener('resize',closePopover);window.addEventListener('scroll',()=>{if(!$('popover').hidden)closePopover();},{passive:true});
initialize();
